use std::fs::File;
use std::io::{self, Read};
use std::num::ParseIntError;

// ---- Result represents success (Ok) or failure (Err) ----

// ---- Function that returns Result ----
fn divide(numerator: f64, denominator: f64) -> Result<f64, String> {
    if denominator == 0.0 {
        Err(String::from("Cannot divide by zero!"))
    } else {
        Ok(numerator / denominator)
    }
}

// ---- Parsing a number ----
fn parse_number(s: &str) -> Result<i32, ParseIntError> {
    s.parse()
}

// ---- Custom error type ----
#[derive(Debug)]
enum GameError {
    InvalidInput,
    OutOfBounds,
    NotEnoughGold,
    PlayerNotFound,
}

fn get_player_health(id: i32) -> Result<i32, GameError> {
    if id < 0 {
        Err(GameError::InvalidInput)
    } else if id > 10 {
        Err(GameError::PlayerNotFound)
    } else {
        Ok(100)
    }
}

fn main() {
    // ---- Using Result with match ----
    let result = divide(10.0, 2.0);
    match result {
        Ok(value) => println!("Success: {}", value),
        Err(e) => println!("Error: {}", e),
    }

    let result2 = divide(10.0, 0.0);
    match result2 {
        Ok(value) => println!("Success: {}", value),
        Err(e) => println!("Error: {}", e),
    }

    // ---- unwrap and expect ----
    // Use with caution!
    let value = divide(10.0, 2.0).unwrap();
    println!("Unwrapped: {}", value);

    // ---- expect (custom panic message) ----
    // let error = divide(10.0, 0.0).expect("Division by zero should not happen");

    // ---- ? operator (propagates errors) ----
    // Can only be used in functions that return Result
    fn read_file() -> Result<String, io::Error> {
        let mut file = File::open("hello.txt")?;
        let mut contents = String::new();
        file.read_to_string(&mut contents)?;
        Ok(contents)
    }

    let contents = read_file();
    match contents {
        Ok(text) => println!("File contents: {}", text),
        Err(e) => println!("Error reading file: {}", e),
    }

    // ---- Parsing ----
    let num = parse_number("42");
    let invalid = parse_number("abc");

    println!("parse_number(\"42\"): {:?}", num);
    println!("parse_number(\"abc\"): {:?}", invalid);

    // ---- Custom errors ----
    let health = get_player_health(5);
    let invalid_id = get_player_health(-1);
    let not_found = get_player_health(20);

    println!("Health: {:?}", health);
    println!("Invalid: {:?}", invalid_id);
    println!("Not found: {:?}", not_found);

    // ---- Result methods ----
    let result = Ok(42);
    let doubled = result.map(|n| n * 2);
    println!("Doubled: {:?}", doubled);

    let result = Err("Error");
    let recovered = result.unwrap_or(0);
    println!("Recovered: {}", recovered);
}

// ---- Propagating errors ----
fn get_player_score(id: i32) -> Result<i32, GameError> {
    // Using ? to propagate errors
    let health = get_player_health(id)?;
    Ok(health * 2)
}

fn main2() {
    let score = get_player_score(5);
    match score {
        Ok(s) => println!("Score: {}", s),
        Err(e) => println!("Error: {:?}", e),
    }
}

